def estimate(points, x):
    """Piecewise linear interpolation.

    * ``points`` must be a non‑empty list of (x, y) sorted by x.
    * If there is only one sample, its y is returned for any x.
    * Values outside the support are clamped to the nearest endpoint y.
    * For interior x, linear interpolation between the surrounding points is performed.
    """
    if not points:
        raise ValueError("no points provided")
    # Single sample case
    if len(points) == 1:
        return points[0][1]
    # Clamp to endpoints
    if x <= points[0][0]:
        return points[0][1]
    if x >= points[-1][0]:
        return points[-1][1]
    # Find interval
    for i in range(1, len(points)):
        left, right = points[i - 1], points[i]
        if x <= right[0]:
            x0, y0 = left
            x1, y1 = right
            # Avoid division by zero (should not happen due to duplicate check)
            if x1 == x0:
                return y0
            return y0 + (y1 - y0) * (x - x0) / (x1 - x0)
    # Fallback (should not reach here)
    return points[-1][1]

